tokens.css:
--color-bg: #f8f0ea;
--color-surface: #ffffff;
--color-text: #2b2622;
--color-text-muted: #6b645d;
--color-border: #e2dbd3;
--color-primary: #97bf29;
--color-on-primary: #1d2409;
--color-accent: #ffcd36;
--color-on-accent: #2b2622;
--font-display: "Bricolage Grotesque", system-ui, sans-serif;
--font-body: "Work Sans", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 18px;
--text-lg: 23px;
--text-xl: 28px;
--text-2xl: 35px;
--text-3xl: 44px;
--radius-control: 8px;
--radius-card: 14px;
--space-section: 128px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
